def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Match two-row motifs to horizontally shifted copies; mark an absent right-hand continuation.
    for tr in range(h-1):
        for sr in range(h-1):
            if sr==tr: continue
            vals=set(grid[sr])|set(grid[sr+1])
            vals.discard(0)
            if len(vals)!=1: continue
            color=next(iter(vals))
            if not all(set(grid[r]) <= {0,color} for r in (sr,sr+1,tr,tr+1)): continue
            for dx in range(1,w):
                miss=[]
                valid=True
                for k in range(2):
                    rowt=grid[tr+k]; rows=grid[sr+k]
                    # target must agree on the overlap, except a missing foreground suffix
                    rowmiss=[]
                    for c in range(dx,w):
                        expected=rows[c-dx]
                        if expected==color and rowt[c]==0:
                            rowmiss.append(c)
                        elif expected != rowt[c]:
                            valid=False; break
                    if not valid: break
                    if rowmiss and rowmiss != list(range(rowmiss[0],w)):
                        valid=False; break
                    miss.append(rowmiss)
                if valid and miss[0] and miss[0]==miss[1]:
                    for k in range(2):
                        for c in miss[k]: out[tr+k][c]=1
    return out

